"""Backend abstraction for CLI."""

from __future__ import annotations

import os
from abc import ABC, abstractmethod

from core import CustomerOutcomeNotFoundError, ODIService, ValueOutOfRangeError
from core.repository import Repository
from core.sqlite_repository import SQLiteRepository


class Backend(ABC):
    @abstractmethod
    def call(self, tool_name: str, args: dict) -> str:
        raise NotImplementedError


class LocalBackend(Backend):
    def __init__(self, db_path: str | None = None) -> None:
        repo: Repository = SQLiteRepository(db_path=db_path)
        self.service = ODIService(repo)

    def call(self, tool_name: str, args: dict) -> str:
        # Delegate to service and format
        if tool_name == "add_customer_outcome":
            co = self.service.add_customer_outcome(
                job_id=args["job_id"],
                customer_value=args["customer_value"],
                business_value=args["business_value"],
                step_id=args.get("step_id"),
            )
            return f"Customer outcome created successfully: {co.model_dump_json()}"
        if tool_name == "get_customer_outcome":
            try:
                co = self.service.get_customer_outcome(args["outcome_id"])
                return co.model_dump_json()
            except CustomerOutcomeNotFoundError as e:
                return str(e)
        if tool_name == "list_customer_outcomes":
            cos = self.service.list_customer_outcomes(args.get("job_id"))
            import json

            return json.dumps([c.model_dump() for c in cos])
        if tool_name == "update_customer_outcome":
            try:
                co = self.service.update_customer_outcome(args["outcome_id"], args)
                return f"Customer outcome updated successfully: {co.model_dump_json()}"
            except (CustomerOutcomeNotFoundError, ValueOutOfRangeError) as e:
                return str(e)
        if tool_name == "delete_customer_outcome":
            try:
                self.service.delete_customer_outcome(args["outcome_id"])
                return f"Customer outcome deleted successfully: {args['outcome_id']}"
            except CustomerOutcomeNotFoundError as e:
                return str(e)
        if tool_name == "compute_opportunity":
            score = self.service.compute_opportunity(args["importance"], args["satisfaction"])
            return f"Opportunity score: {score:.2f}"
        raise NotImplementedError(f"Unknown tool: {tool_name}")


class MCPBackend(Backend):
    def __init__(self, mcp_url: str) -> None:
        self.mcp_url = mcp_url

    def call(self, tool_name: str, args: dict) -> str:
        from cli.outcomes import _call_mcp

        return _call_mcp(tool_name, args, self.mcp_url)


def get_backend(
    backend: str | None = None, db_path: str | None = None, mcp_url: str | None = None
) -> Backend:
    if backend is None:
        backend = os.environ.get("AGENTIC_ODI_BACKEND", "local")
    if backend == "local":
        return LocalBackend(db_path=db_path)
    if backend == "mcp":
        return MCPBackend(
            mcp_url or os.environ.get("AGENTIC_ODI_MCP_URL", "http://localhost:8000/mcp")
        )
    raise ValueError(f"Unknown backend: {backend}")
    direction: DirectionOption = typer.Option(..., help="minimize | maximize"),  # noqa: B008
    unit_of_measure: str = typer.Option(..., "--unit"),
    object_of_control: str = typer.Option(..., "--object"),
    statement: str = typer.Option(..., help="Full outcome statement"),
    importance: float = typer.Option(..., min=1.0, max=10.0),
    satisfaction: float = typer.Option(..., min=1.0, max=10.0),
    category: CategoryOption = typer.Option(..., help="Business impact category"),  # noqa: B008
    business_statement: str = typer.Option(..., help="Business value statement"),
    contextual_clarifier: str | None = typer.Option(default=None),
    step_id: str | None = typer.Option(default=None),
    mcp_url: str = typer.Option(default=MCP_URL_DEFAULT, help="MCP server URL"),
) -> None:
    """Add a Customer Outcome with customer and business value."""
    customer_value = {
        "direction": direction.value,
        "unit_of_measure": unit_of_measure,
        "object_of_control": object_of_control,
        "statement": statement,
        "importance": importance,
        "satisfaction": satisfaction,
    }
    if contextual_clarifier:
        customer_value["contextual_clarifier"] = contextual_clarifier
    business_value = {
        "category": category.value,
        "statement": business_statement,
    }
    args: dict[str, Any] = {
        "job_id": job_id,
        "customer_value": customer_value,
        "business_value": business_value,
    }
    if step_id:
        args["step_id"] = step_id
    from cli.backend import get_backend

    typer.echo(get_backend("mcp", mcp_url=mcp_url).call("add_customer_outcome", args))


@outcomes_app.command("get")
def get(
    outcome_id: str = typer.Argument(...),
    mcp_url: str = typer.Option(default=MCP_URL_DEFAULT, help="MCP server URL"),
) -> None:
    """Get a Customer Outcome by ID."""
    from cli.backend import get_backend

    typer.echo(
        get_backend("mcp", mcp_url=mcp_url).call("get_customer_outcome", {"outcome_id": outcome_id})
